10	// Booleans, BigInts, and finite integral numbers count as "int-like" in Python terms.
11	export function pythonIntLike(value) {
12	  if (typeof value === 'boolean' || typeof value === 'bigint') return true;
13	  return typeof value === 'number' && Number.isFinite(value) && Math.floor(value) === value;
14	}
