41	export class PyFrozenSet {
42	  constructor(items) {
43	    // Frozensets dedupe members by Python equality.
44	    const deduped = [];
45	    for (const item of items) {
46	      if (!deduped.some((existing) => pythonEquals(existing, item))) deduped.push(item);
47	    }
48	    this.items = deduped;
49	  }
