140	// Ordering across bool/int(BigInt)/float, exact for integral values. For a
141	// nonintegral double n and integer i: i < n iff i <= floor(n), n < i iff
142	// ceil(n) <= i — this avoids precision loss from Number(bigint) rounding.
143	function numericLessThan(a, b) {
144	  const x = asNumeric(a);
145	  const y = asNumeric(b);
146	  const xBig = typeof x === 'bigint';
147	  const yBig = typeof y === 'bigint';
148	  if (xBig && yBig) return x < y;
149	  if (!xBig && !yBig) {
150	    if (Number.isNaN(x) || Number.isNaN(y)) return false; // Python: NaN < x is False
151	    return x < y;
152	  }
153	  if (xBig) {
154	    if (Number.isNaN(y)) return false;
155	    if (y === Infinity) return true;
156	    if (y === -Infinity) return false;
157	    if (Number.isInteger(y)) return x < BigInt(y);
158	    return x <= BigInt(Math.floor(y));
159	  }
160	  if (Number.isNaN(x)) return false;
161	  if (x === Infinity) return false;
162	  if (x === -Infinity) return true;
163	  if (Number.isInteger(x)) return BigInt(x) < y;
164	  return BigInt(Math.ceil(x)) <= y;
165	}
