export function parsePythonExpression(source) {
  if (typeof source !== 'string') {
    throw new TypeError('parsePythonExpression() argument must be a string');
  }
  const tokens = tokenize(source);
  let pos = 0;

  const peek = () => tokens[pos];
  const isOp = (v) => peek().t === 'op' && peek().v === v;
  const eatOp = (v) => {
    if (isOp(v)) {
      pos++;
      return true;
    }
    return false;
  };
  const expectOp = (v) => {
    if (!eatOp(v)) throw new SyntaxError('invalid syntax');
  };

  // expr (',' expr)* [','] — a trailing comma or 2+ items make a tuple.
  function parseTestlist(atEof) {
    const first = parseExpr();
    if (!isOp(',')) return first;
    const items = [first];
    while (eatOp(',')) {
      if (atEof ? peek().t === 'eof' : isOp(')')) break;
      items.push(parseExpr());
    }
    return new PyTuple(items);
  }

  function parseExpr() {
    return parseAddSub();
  }

  function parseAddSub() {
    let left = parseMulDiv();
    while (true) {
      if (eatOp('+')) left = binaryOp('+', left, parseMulDiv());
      else if (eatOp('-')) left = binaryOp('-', left, parseMulDiv());
      else return left;
    }
  }

  function parseMulDiv() {
    let left = parseUnary();
    while (true) {
      if (eatOp('*')) left = binaryOp('*', left, parseUnary());
      else if (eatOp('/')) left = binaryOp('/', left, parseUnary());
      else if (eatOp('//')) left = binaryOp('//', left, parseUnary());
      else if (eatOp('%')) left = binaryOp('%', left, parseUnary());
      else return left;
    }
  }

  // Python precedence: unary binds looser than ** on its left (-2**2 == -4),
  // but **'s right operand is itself a unary expression (2**-2 == 0.25).
  function parseUnary() {
    if (eatOp('-')) return unaryOp('-', parseUnary());
    if (eatOp('+')) return unaryOp('+', parseUnary());
    return parsePower();
  }

  function parsePower() {
    const base = parseAtomExpr();
    if (eatOp('**')) return binaryOp('**', base, parseUnary());
    return base;
  }

  function parseAtomExpr() {
    if (peek().t === 'name') {
      const name = peek().v;
      pos++;
      if (name === 'None' || name === 'True' || name === 'False') {
        const v = name === 'None' ? null : name === 'True';
        if (isOp('(')) {
          throw new TypeError(
            "'" + (name === 'None' ? 'NoneType' : 'bool') + "' object is not callable"
          );
        }
        return v;
      }
      if (isOp('(')) return parseCall(name);
      if (BUILTINS[name]) {
        throw pyError('NameError', "builtin '" + name + "' cannot be used as a value");
      }
      throw pyError('NameError', "name '" + name + "' is not defined");
    }
    const v = parseAtom();
    if (isOp('(')) {
      throw new TypeError("'" + typeName(v) + "' object is not callable");
    }
    return v;
  }

  function parseCall(name) {
    expectOp('(');
    const args = [];
    if (!eatOp(')')) {
      while (true) {
        if (peek().t === 'name' && tokens[pos + 1] && tokens[pos + 1].t === 'op' &&
            tokens[pos + 1].v === '=') {
          throw new SyntaxError('keyword arguments are not supported');
        }
        args.push(parseExpr());
        if (eatOp(',')) {
          if (eatOp(')')) break;
          continue;
        }
        expectOp(')');
        break;
      }
    }
    const fn = BUILTINS[name];
    if (!fn) throw pyError('NameError', "name '" + name + "' is not defined");
    return fn(args);
  }

  function parseAtom() {
    const tok = peek();
    if (tok.t === 'int' || tok.t === 'float' || tok.t === 'complex') {
      pos++;
      return tok.v;
    }
    if (tok.t === 'str' || tok.t === 'bytes') {
      pos++;
      // Adjacent literal concatenation: 'a' "b" -> 'ab'.
      let acc = tok;
      while (peek().t === 'str' || peek().t === 'bytes') {
        const nt = peek();
        pos++;
        if ((acc.t === 'bytes') !== (nt.t === 'bytes')) {
          throw new SyntaxError('cannot mix bytes and nonbytes literals');
        }
        acc = acc.t === 'bytes'
          ? { t: 'bytes', v: concatBytes(acc.v, nt.v) }
          : { t: 'str', v: acc.v + nt.v };
      }
      return acc.t === 'bytes' ? new PyBytes(acc.v) : acc.v;
    }
    if (isOp('(')) {
      pos++;
      if (eatOp(')')) return new PyTuple([]);
      const val = parseTestlist(false);
      expectOp(')');
      return val;
    }
    if (isOp('[')) {
      pos++;
      const items = [];
      if (!eatOp(']')) {
        while (true) {
          items.push(parseExpr());
          if (eatOp(',')) {
            if (eatOp(']')) break;
            continue;
          }
          expectOp(']');
          break;
        }
      }
      return items;
    }
    if (isOp('{')) {
      pos++;
      if (eatOp('}')) return new PyDict();
      const first = parseExpr();
      if (eatOp(':')) {
        const d = new PyDict();
        d.set(first, parseExpr());
        while (eatOp(',')) {
          if (eatOp('}')) return d;
          const k = parseExpr();
          expectOp(':');
          d.set(k, parseExpr());
        }
        expectOp('}');
        return d;
      }
      const items = [first];
      while (eatOp(',')) {
        if (isOp('}')) break;
        items.push(parseExpr());
      }
      expectOp('}');
      return new PySet(items);
    }
    throw new SyntaxError('invalid syntax');
  }

  const result = parseTestlist(true);
  if (peek().t !== 'eof') throw new SyntaxError('invalid syntax');
  return result;
}

